        // ==================== الأربعون النبوية (من قاعدة المرجع) ====================,
        DuaItem(41, CAT_ARBAEEN, "حديث : إنما الأعمال بالنيات",
            "عن أمير المؤمنين أبي حفص عمر بن الخطاب رضي الله عنه ، قال : سمعت رسول الله صلى الله عليه وسلم يقول : ( إنما الأعمال بالنيّات ، وإنما لكل امريء مانوى ، فمن كانت هجرته إلى الله ورسوله ، فهجرته إلى الله ورسوله ، ومن كانت هجرته لدنيا يصيبها ، أو امرأة ينكحها ، فهجرته إلى ما هاجر إليه )",
            "رواه البخاري ومسلم في صحيحهما ."),
        DuaItem(42, CAT_ARBAEEN, "حديث جبريل عليه السلام",
            "عن عمر بن الخطاب رضي الله عنه قال : بينما نحن جلوس عند رسول الله صلى الله عليه وسلم ذات يوم ، إذ طلع علينا رجل شديد بياض الثياب ، شديد سواد الشعر ، لا يرى عليه أثر السفر ، ولا يعرفه منا أحد ، حتى جلس إلى النبي صلى الله عليه وسلم فأسند ركبته إلى ركبتيه ، ووضع كفيه على فخذيه ، وقال : \" يا محمد أخبرني عن الإسلام \" ، فقال له : ( الإسلام أن تشهد أن لا إله إلا الله وأن محمدا رسول الله ، وتقيم الصلاة وتؤتي الزكاة ، وتصوم رمضان ، وتحج البيت إن استطعت إليه سبيلا ) ، قال : \" صدقت \" ، فعجبنا له يسأله ويصدقه ، قال : \" أخبرني عن الإيمان \" قال : ( أن تؤمن بالله وملائكته وكتبه ورسله واليوم الآخر ، وتؤمن بالقدر خيره وشره ) ، قال : \" صدقت \" ، قال : \" فأخبرني عن الإحسان \" ، قال : ( أن تعبد الله كأنك تراه ، فإن لم تكن تراه فإنه يراك ) ، قال : \" فأخبرني عن الساعة \" ، قال : ( ما المسؤول بأعلم من السائل ) ، قال : \" فأخبرني عن أماراتها \" ، قال : ( أن تلد الأمة ربتها ، وأن ترى الحفاة العراة العالة رعاء الشاء ، يتطاولون في البنيان ) ثم انطلق فلبث مليا ، ثم قال : ( يا عمر ، أتدري من السائل ؟ ) ، قلت : \"الله ورسوله أعلم \" ، قال : ( فإنه جبريل أتاكم يعلمكم دينكم )",
            "رواه مسلم ."),
        DuaItem(43, CAT_ARBAEEN, "حديث : بُني الإسلام على خمس",
            "عن أبي عبد الرحمن عبد الله بن عمر بن الخطاب رضي الله عنهما قال : سمعت رسول الله صلى الله عليه وسلم يقول : ( بني الإسلام على خمس : شهادة أن لا إله إلا الله ، وأن محمدا رسول الله ، وإقام الصلاة ، وإيتاء الزكاة ، وحج البيت ، وصوم رمضان )",
            "رواه البخاري ومسلم ."),
        DuaItem(44, CAT_ARBAEEN, "حديث: إن أحدكم يُجمع خلقه",
            "عن أبي عبد الرحمـن عبد الله بن مسعود رضي الله عنه ، قال : حدثنا رسول الله صلى الله عليه وسلم وهو الصادق المصدوق قال : ( إن أحدكم يُجمع خلقه في بطن أمه أربعين يوما نطفةً ، ثم يكون علقةً مثل ذلك ، ثم يكون مضغةً مثل ذلك ، ثم يُرسل إليه الملك فينفخ فيه الروح ، ويُؤمر بأربع كلمات : بكتب رزقه ، وأجله ، وعمله ، وشقي أم سعيد . فوالله الذي لا إله غيره ، إن أحدكم ليعمل بعمل أهل الجنة ، حتى ما يكون بينه وبينها إلا ذراع ، فيسبق عليه الكتاب فيعمل بعمل أهل النار ، وإن أحدكم ليعمل بعمل أهل النار حتى ما يكون بينه وبينها إلا ذراع ، فيسبق عليه الكتاب ، فيعمل بعمل أهل الجنة )",
            "رواه البخاري ومسلم ."),
        DuaItem(45, CAT_ARBAEEN, "حديث: من أحدث في أمرنا هذا",
            "عن أم المؤمنين عائشة رضي الله عنها قالت : قال رسول الله صلى الله عليه وسلم : ( من أحدث في أمرنا هذا ما ليس منه فهو رد ) رواه البخاري ومسلم ، وفي رواية لمسلم : ( من عمل عملاً ليس عليه أمرنا فهو رد ) .",
            "رواه البخاري ومسلم ."),
        DuaItem(46, CAT_ARBAEEN, "حديث : الحلال بيّن والحرام بيّن",
            "عن أبي عبد الله النعمان بن بشير رضي الله عنهما قال : سمعت رسول الله صلى الله عليه وسلم يقول : ( إن الحلال بيّن والحرام بيّن ، وبينهما أمور مشتبهات لا يعلمهن كثير من الناس ، فمن اتقى الشبهات فقد استبرأ لدينه وعرضه ، ومن وقع في الشبهات فقد وقع في الحرام ، كالراعي يرعى حول الحمى يوشك أن يرتع فيه ، ألا وأن لكل ملك حمى ، ألا وإن حمى الله محارمه ، إلا وإن في الجسد مضغة إذا صلحت صلح الجسد كله ، وإذا فسدت فسد الجسد كله ، ألا وهي القلب )",
            "رواه البخاري ومسلم ."),
        DuaItem(47, CAT_ARBAEEN, "حديث : الدين النصيحة",
            "عن تميم بن أوس رضي الله عنه ، أن النبي صلى الله عليه وسلم قال : ( الدين النصيحة ، قلنا : لمن يا رسول الله ؟ قال : لله ، ولكتابه ، ولرسوله ، ولأئمة المسلمين وعامتهم )",
            "رواه البخاري ومسلم ."),
        DuaItem(48, CAT_ARBAEEN, "حديث : أُمرت أن أقاتل الناس",
            "عن ابن عمر رضي الله عنهما ، أن رسول الله صلى الله عليه وسلم قال : ( أمرت أن أقاتل الناس ، حتى يشهدوا أن لا إله إلا الله ، وأن محمدا رسول الله ، ويقيموا الصلاة ، ويؤتوا الزكاة ، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام ، وحسابهم على الله تعالى )",
            "رواه البخاري ومسلم ."),
        DuaItem(49, CAT_ARBAEEN, "حديث : ما نهيتكم عنه فاجتنبوه",
            "ن أبي هريرة رضي الله عنه ، قال : سمعت رسول الله صلى الله عليه وسلم يقول : ( ما نهيتكم عنه فاجتنبوه ، وما أمرتكم به فأتوا منه ما استطعتم ؛ فإنما أهلك الذين من قبلكم كثرة مسائلهم ، واختلافهم على أنبيائهم )",
            "رواه البخاري ومسلم ."),
        DuaItem(50, CAT_ARBAEEN, "حديث : إن الله طيب لا يقبل إلا طيبا",
            "عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( إن الله طيب لا يقبل إلا طيبا ، وإن الله أمر المؤمنين بما أمر به المرسلين ، فقال تعالى : { يا أيها الرسل كلوا من الطيبات واعملوا صالحا } ( المؤمنون : 51 ) ، وقال تعالى : { يا أيها الذين آمنوا كلوا من طيبات ما رزقناكم } ( البقرة : 172 ) ، ثم ذكر الرجل يطيل السفر ، أشعث أغبر ، يمدّ يديه إلى السماء : يا رب يا رب ، ومطعمه حرام ، ومشربه حرام ، وملبسه حرام ، وغُذّي بالحرام ، فأنّى يُستجاب له ؟ )",
            "رواه مسلم ."),
        DuaItem(51, CAT_ARBAEEN, "حديث : دع ما يريبك إلى ما لا يريبك",
            "عن الحسن بن علي بن أبي طالب سبط رسول الله وريحانته رضي الله عنه قال : حفظت من رسول الله صلى الله عليه وسلم : ( دع ما يريبك ، إلى ما لا يريبك )",
            "رواه الترمذي وقال : حديث حسن صحيح ."),
        DuaItem(52, CAT_ARBAEEN, "حديث : من حُسن إسلام المرء تركه ما لا يعنيه",
            "عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( من حسن إسلام المرء تركه ما لا يعنيه )",
            "حديث حسن رواه الترمذي وغيره ."),
        DuaItem(53, CAT_ARBAEEN, "حديث : لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه",
            "عن أنس بن مالك رضي الله عنه خادم رسول الله صلى الله عليه وسلم أن النبي صلى الله عليه وسلم  قال : ( لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه )",
            "رواه البخاري ومسلم ."),
        DuaItem(54, CAT_ARBAEEN, "حديث : لا يحل دم امرئ مسلم إلا بإحدى ثلاث",
            "عن ابن مسعود رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( لا يحل دم امرئ مسلم يشهد أن لا إله إلا الله ، وأني رسول الله ، إلا بإحدى ثلاث : الثيّب الزاني ، والنفس بالنفس ، والتارك لدينه المفارق للجماعة )",
            "رواه البخاري ومسلم ."),
        DuaItem(55, CAT_ARBAEEN, "حديث : لا تغضب",
            "عن أبي هريرة رضي الله عنه ، أن رجلا قال للنبي صلى الله عليه وسلم : \" أوصني \" ، قال : ( لا تغضب ) ، فردّد ، قال : ( لا تغضب ) رواه البخاري .",
            "رواه البخاري ."),
        DuaItem(56, CAT_ARBAEEN, "حديث : من كان يؤمن بالله واليوم الآخر فليكرم ضيفه",
            "عن أبي هريرة رضي الله عنه : أن رسول الله صلى الله عليه وسلم قال : ( من كان يؤمن بالله واليوم الآخر ، فليقل خيرا أو ليصمت ، ومن كان يؤمن بالله واليوم الآخر ، فليكرم جاره ، ومن كان يؤمن بالله واليوم الآخر ، فليكرم ضيفه )",
            "رواه البخاري ومسلم ."),
        DuaItem(57, CAT_ARBAEEN, "حديث : فإذا قتلتم فأحسنوا القتلة",
            "عن أبي يعلى شداد بن أوس رضي الله عنه ، عن رسول الله صلى الله عليه وسلم قال : ( إن الله كتب الإحسان على كل شيء ، فإذا قتلتم فأحسنوا القتلة ، وإذا ذبحتم فأحسنوا الذبح ، وليحد أحدكم شفرته ، وليرح ذبيحته )",
            "رواه مسلم ."),
        DuaItem(58, CAT_ARBAEEN, "حديث : اتق الله حيثما كنت",
            "عن أبي ذر جندب بن جنادة ، وأبي عبد الرحمن معاذ بِن جبل رضي الله عنهما، عن رسول الله صلى الله عليه وسلم قال: ( اتق الله حيثما كنت، وأتبع السيئة الحسنة تمحها ، وخالق الناس بخلق حسن )",
            "رواه الترمذي وقال : حديث حسن صحيح ."),
        DuaItem(59, CAT_ARBAEEN, "حديث : احفظ الله يحفظك",
            "عن أبي العباس عبد الله بن عباس رضي الله عنهما قال : كنت خلف النبي صلى الله عليه وسلم يوما ، فقال : ( يا غلام ، إني أُعلمك كلمات : احفظ الله يحفظك ، احفظ الله تجده تجاهك ، إذا سأَلت فاسأَل الله ، وإذا استعنت فاستعن بالله ، واعلم أن الأُمة لو اجتمعت على أَن ينفعـوك بشيء ، لم ينفعوك إلا بشيء قد كتبه الله لك ، وإن اجتمعوا على أن يضروك بشيء ، لم يضروك إلا بشيء قد كتبه الله عليك، رفعت الأقلام وجفت الصحف ) \n\nوفي رواية الإمام أحمد : ( احفظ الله تجده أَمامك ، تعرف إلى الله في الرخاء يعرفك فـي الشدة، واعلم أَن ما أَخطأَك لم يكن ليصيبك ، وما أَصابك لم يكن ليخطئك ، واعلم أَن النصر مع الصبر ، وأن الفرج مع الكرب ، وأن مع العسرِ يسرا ) .",
            "رواه الترمذي وقال : حديث حسن صحيح ."),
        DuaItem(60, CAT_ARBAEEN, "حديث : إذا لم تستح فاصنع ما شئت",
            "عن أبي مسعود رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( إن مما أدرك الناس من كلام النبوة الأولى : إذا لم تستح فاصنع ما شئت )",
            "رواه البخاري ."),
        DuaItem(61, CAT_ARBAEEN, "حديث : قل آمنت بالله ثم استقم",
            "عن أبي عمرو سفيان بن عبد الله الثقفي ، رضي الله عنه قال : قلت : يا رسول الله ، قل لي في الإسلام قولاً لا أسأل عنه أحدا غيرك ، قال : ( قل آمنت بالله ، ثم استقم )",
            "رواه مسلم في صحيحه ."),
        DuaItem(62, CAT_ARBAEEN, "حديث : أرأيت إذا صليت المكتوبات",
            "عن أبي عبد الله جابر بن عبد الله الأنصاري رضي الله عنهما ، أن رجلا سأل رسول الله عليه وسلم فقال : أرأيت إذا صليت الصلوات المكتوبات ، وصمت رمضان ، وأحللت الحلال ، وحرمت الحرام ، ولم أزد على ذلك شيئا ، أأدخل الجنة ؟ ، قال : ( نعم )",
            "رواه مسلم ."),
        DuaItem(63, CAT_ARBAEEN, "حديث : الطهور شطر الإيمان",
            "عن أبي مالك الحارث بن عاصم الأشعري رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( الطهور شطر الإيمان ، والحمد لله تملأ الميزان ، وسبحان الله والحمد لله تملآن - تملأ - ما بين السماوات والأرض ، والصلاة نور ، والصدقة برهان ، والصبر ضياء ، والقرآن حجة لك أو عليك ، كل الناس يغدو ، فبائع نفسه ، فمعتقها أو موبقها )",
            "رواه مسلم ."),
        DuaItem(64, CAT_ARBAEEN, "حديث : يا عبادي إني حرمت الظلم على نفسي",
            "عن أبي ذر الغفاري رضي الله عنه ، عن النبي صلى الله عليه وسلم فيما يرويه عن ربِه عز وجل أنه قال : ( يا عبادي إني حرمت الظلم على نفسي ، وجعلته بينكم محرما فلا تظالموا ، يا عبادي كلكم ضال إلا من هديته ، فاستهدوني أهدكم ، يا عبادي كلكم جائع إلا من أطعمته ، فاستطعموني أُطعمكم ، يا عبادي كلكم عار إلا من كسوته ، فاستكسوني أكسكم ، يا عبادي إنكم تخطئون بالليلِ والنهار ، وأنا أغفر الذنوب جميعا فاستغفروني أغفر لكم ، يا عبادي إِنكم لن تبلغوا ضري فتضروني ، ولن تبلغوا نفعي فتنفعوني ، يا عبادي لو أن أولكم وآخركم وإنسكم وجنكم كانوا على أتقى قلب رجل واحد منكم ما زاد ذلك في ملكي شيئا ، يا عبادي لو أن أولكم وآخركم وإنسكم وجنكم كانوا على أفجرِ قلب واحد منكم ما نقص من ملكي شيئا ، يا عبادي لو أن أولكم وآخركم وإنسكم وجنكم قاموا في صعيد واحد فسألوني ، فأعطيت كل واحد مسألته ما نقص ذلك مما عندي إلا كما ينقص المخيط إذا أدخل البحر ، يا عِبادي إنما هي أعمالكم أحصيها لكم ثم أوفيكم إياها ، فمن وجد خيرا فليحمد الله ، ومن وجد غير ذلك فلا يلومن إلا نفسه )",
            "رواه مسلم ."),
        DuaItem(65, CAT_ARBAEEN, "حديث : ذهب أهل الدثور بالأجور",
            "عن أبي ذر الغفاري رضي الله عنه أن ناسا من أصحاب رسول الله صلى الله عليه وسلم قالوا له : يا رسول الله ، ذهب أهل الدثور بالأجور ، يصلون كما نصلي ، ويصومون كما نصوم ، ويتصدقون بفضول أموالهم . قال : ( أوليس قد جعل الله لكم ما تصدّقون ؟ إن لكم بكل تسبيحة صدقة ، وكل تكبيرة صدقة ، وكل تحميدة صدقة ، وكل تهليلة صدقة ، وأمر بالمعروف صدقة ، ونهي عن منكر صدقة ، وفي بضع أحدكم صدقة ) ، قالوا : يا رسول الله ، أيأتي أحدنا شهوته ويكون له فيها أجر ؟ ، قال : ( أرأيتم لو وضعها في حرام ، أكان عليه وزر ؟ فكذلك إذا وضعها في حلال كان له أجر )",
            "رواه مسلم ."),
        DuaItem(66, CAT_ARBAEEN, "حديث : كل سلامى من الناس عليه صدقة",
            "عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( كل سلامى من الناس عليه صدقة ، كل يوم تطلع فيه الشمس : تعدل بين اثنين صدقة ، وتعين الرجل في دابّته فتحمله عليها أو ترفع له متاعه صدقة ، والكلمة الطيبة صدقة ، وبكل خطوة تمشيها إلى الصلاة صدقة ، وتميط الأذى عن الطريق صدقة )",
            "رواه البخاري ومسلم ."),
        DuaItem(67, CAT_ARBAEEN, "حديث : البر حسن الخلق",
            "عن النواس بن سمعان رضي الله عنه عن النبي صلى الله عليه وسلم قال : ( البرّ حسن الخلق ، والإثم ما حاك في نفسك ، وكرهت أن يطلع عليه الناس ) رواه مسلم .\nوعن وابصة بن معبد رضي الله عنه قال : أتيت رسول الله صلى الله عليه وسلم فقال : ( جئت تسأل عن البرّ ؟ ) ، قلت : نعم ، فقال : ( استفت قلبك ، البرّ ما اطمأنت إليه النفس واطمأن إليه القلب ، والإثم ما حاك في النفس وتردد في الصدر ، وإن أفتاك المفتون )",
            "حديث حسن رُويناه في مسندي الإمامين : أحمد بن حنبل ، والدارمي بإسناد حسن ."),
        DuaItem(68, CAT_ARBAEEN, "حديث : فعليكم بسنتي",
            "عن أبي نجيح العرباض بن سارية رضي الله عنه قال : وعظنا رسول الله صلى الله عليه وسلم موعظة وجلت منها القلوب ، وذرفت منها العيون ، فقلنا : يا رسول الله ، كأنها موعظة مودع فأوصنا ، قال : ( أوصيكم بتقوى الله ، والسمع والطاعة ، وإن تأمّر عليكم عبد ؛ فإنه من يعش منكم فسيرى اختلافا كثيرا ، فعليكم بسنتي وسنة الخلفاء الراشدين المهديين ، عضّوا عليها بالنواجذ ، وإياكم ومحدثات الأمور ، فإن كل بدعة ضلالة )",
            "رواه أبو داود والترمذي وقال: حديث حسن صحيح."),
        DuaItem(69, CAT_ARBAEEN, "حديث : ألا أدلك على أبواب الخير",
            "عن معاذ بن جبل رضي الله عنه قال : قلت يا رسول الله ، أخبرني بعمل يُدخلني الجنة ويباعدني من النار ، قال : ( لقد سألت عن عظيم ، وإنه ليسير على من يسّره الله عليه : تعبد الله لا تُشرك به شيئا ، وتقيم الصلاة وتؤتي الزكاة ، وتصوم رمضان ، وتحجّ البيت ) ثم قال له : ( ألا أدلك على أبواب الخير ؟ الصوم جنّة ، والصدقة تطفيء الخطيئة كما يُطفيء الماء النار ، وصلاة الرجل في جوف الليل ) ، ثم تلا : { تتجافى جنوبهم عن المضاجع } حتى بلغ : { يعملون } ( السجدة : 16 – 17 ) ، ثم قال : ( ألا أخبرك برأس الأمر وعموده وذروة سنامه ؟ ) ، قلت : بلى يا رسول الله . قال : ( رأس الأمر الإسلام ، وعموده الصلاة ، وذروة سنامه الجهاد ) ، ثم قال : ( ألا أخبرك بملاك ذلك كله ؟ ) قلت : بلى يا رسول الله . فأخذ بلسانه ثم قال : ( كفّ عليك هذا ) ، قلت : يا نبي الله ، وإنا لمؤاخذون بما نتكلم به ؟ ، فقال : ( ثكلتك أمك يا معاذ ، وهل يكب الناس في النار على وجوههم - أو قال على مناخرهم - إلا حصائد ألسنتهم ؟ )",
            "رواه الترمذي وقال : حديث حسن صحيح"),
        DuaItem(70, CAT_ARBAEEN, "حديث : إن الله فرض فرائض فلا تضيِّعوها",
            "عن أبي ثعلبة الخشني رضي الله عنه عن رسول الله صلى الله عليه وسلم قال : ( إن الله تعالى فرض فرائض فلا تضيّعوها ، وحدّ حدودا فلا تعتدوها ، وحرّم أشياء فلا تنتهكوها ، وسكت عن أشياء - رحمة لكم غير نسيان - فلا تبحثوا عنها )",
            "حديث حسن ، رواه الدارقطني وغيره ."),
        DuaItem(71, CAT_ARBAEEN, "حديث : ازهد في الدنيا يحبك الله",
            "ن أبي العباس سهل بن سعد الساعدي رضي الله عنه قال : جاء رجل إلى النبي صلى الله عليه وسلم فقال : يا رسول الله ، دلّني على عمل إذا عملته أحبني الله وأحبّني الناس ، فقال : ( ازهد في الدنيا يحبّك الله ، وازهد فيما عند الناس يحبّك الناس )",
            "رواه ابن ماجة ."),
        DuaItem(72, CAT_ARBAEEN, "حديث : لا ضرر ولا ضرار",
            "عن أبي سعيد سعد بن سنان الخدري رضي الله عنه : أن رسول الله صلى الله عليه وسلم قال : ( لا ضرر ولا ضرار )",
            "حديث حسن رواه ابن ماجة والدارقطني وغيرهما مسندا ، ورواه مالك في الموطأ مرسلا : عن عمرو بن يحيى عن أبيه عن النبي صلى الله عليه وسلم ، فأسقط أبا سعيد ، وله طرق يقوي بعضها بعضا ."),
        DuaItem(73, CAT_ARBAEEN, "حديث : البينة على المدعي",
            "عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال : ( لو يُعطى الناس بدعواهم ، لادّعى رجالٌ أموال قوم ودماءهم ، لكن البيّنة على المدّعي واليمين على من أنكر )",
            "حديث حسن رواه البيهقي وغيره هكذا ، وبعضه في الصحيحين ."),
        DuaItem(74, CAT_ARBAEEN, "حديث : من رأى منكم منكرا فليغيره",
            "عن أبي سعيد الخدري رضي الله عنه قال : سمعت رسول الله صلى الله عليه وسلم يقول : ( من رأى منكم منكرا فليغيره بيده ، فإن لم يستطع فبلسانه ، فإن لم يستطع فبقلبه ، وذلك أضعف الإيمان )",
            "رواه مسلم ."),
        DuaItem(75, CAT_ARBAEEN, "حديث : وكونوا عباد الله إخوانا",
            "عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( لا تحاسدوا ، ولا تناجشوا ، ولا تباغضوا ، ولا تدابروا ، ولا يبع بعضكم على بيع بعض ، وكونوا عباد الله إخوانا ، المسلم أخو المسلم ، لا يظلمه ولا يخذله ولا يحقره ، التقوى هاهنا – ويشير إلى صدره ثلاث مرات – بحسب امرئ من الشر أن يحقر أخاه المسلم ، كل المسلم على المسلم حرام : دمه وماله وعرضه )",
            "رواه مسلم ."),
        DuaItem(76, CAT_ARBAEEN, "حديث : من نفس عن مؤمن كُربة",
            "عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( من نفس عن مؤمن كربة من كرب الدنيا ، نفس الله عنه كربة من كرب يوم القيامة ، ومن يسّر على معسر ، يسّر الله عليه في الدنيا والآخرة ، ومن ستر مؤمنا ستره الله في الدنيا والآخرة ، والله في عون العبد ما كان العبد في عون أخيه ، ومن سلك طريقا يلتمس فيه علما ، سهل الله له به طريقا إلى الجنة ، وما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله ويتدارسونه بينهم ، إلا نزلت عليهم السكينة ، وغشيتهم الرحمة ، وحفتهم الملائكة ، وذكرهم الله فيمن عنده ، ومن بطّأ به عمله ، لم يسرع به نسبه )",
            "رواه مسلم ."),
        DuaItem(77, CAT_ARBAEEN, "حديث : إن الله كتب الحسنات والسيئات",
            "عن ابن عباس رضي الله عنهما عن رسول الله صلى الله عليه وسلم فيما يرويه عن ربه تبارك وتعالى قال : ( إن الله كتب الحسنات والسيئات ثم بيّن : فمن همّ بحسنة فلم يعملها كتبها الله عنده حسنة كاملة ، وإن همّ بها فعملها كتبها الله عنده عشر حسنات إلى سبعمئة ضعف ، وإن همّ بسيئة فلم يعملها كتبها الله عنده حسنة كاملة ، وإن همّ بها فعملها كتبها الله سيئة واحدة )",
            "رواه البخاري ومسلم في صحيحيهما."),
        DuaItem(78, CAT_ARBAEEN, "حديث : من عادى لي وليا فقد آذنته بالحرب",
            "عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : ( إن الله تعالى قال : من عادى لي وليا فقد آذنته بالحرب ، وما تقرّب إليّ عبدي بشيء أحبّ إليّ مما افترضته عليه ، وما يزال عبدي يتقرّب إليّ بالنوافل حتى أُحبّه ، فإذا أحببته كنت سمعه الذي يسمع به ، وبصره الذي يبصر به ، ويده التي يبطش بها ، ورجله التي يمشي بها ، وإن سألني لأعطينّه ، ولئن استعاذني لأعيذنّه )",
            "رواه البخاري ."),
        DuaItem(79, CAT_ARBAEEN, "حديث : رفع عن أمتي الخطأ والنسيان",
            "عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال : ( إن الله تجاوز عن أمتي الخطأ والنسيان وما استُكرهوا عليه )",
            "حديث حسن رواه ابن ماجة والبيهقي وغيرهما ."),
        DuaItem(80, CAT_ARBAEEN, "حديث : كن في الدنيا كأنك غريب",
            "عن ابن عمر رضي الله عنهما قال : أخذ رسول الله صلى الله عليه وسلم بمنكبيّ فقال : ( كن في الدنيا كأنك غريب ، أو عابر سبيل ) ، وكان ابن عمر رضي الله عنهما يقول : \" إذا أمسيت فلا تنتظر الصباح ، وإذا أصبحت فلا تنتظر المساء ، وخذ من صحتك لمرضك ، ومن حياتك لموتك \"",
            "رواه البخاري ."),
        DuaItem(81, CAT_ARBAEEN, "حديث : حتى يكون هواه تبعا لما جئت به",
            "عن عبد الله بن عمرو بن العاص رضي الله عنهما قال : قال رسول الله صلى الله عليه وسلم : ( لا يُؤمن أحدكم حتى يكون هواه تبعا لما جئت به )",
            "حديث صحيح رُويناه في كتاب الحجّة بإسناد صحيح ."),
        DuaItem(82, CAT_ARBAEEN, "حديث : إنك ما دعوتني ورجوتني",
            "عن أنس بن مالك رضي الله عنه قال : سمعت رسول الله صلى الله عليه وسلم يقول : ( قال الله عزوجل : يا ابن آدم ، إنك ما دعوتني ورجوتني غفرت لك ما كان منك ولا أبالي ، يا ابن آدم ، لو بلغت ذنوبك عنان السماء ، ثم استغفرتني غفرت لك ، يا ابن آدم ، إنك لو أتيتني بقراب الأرض خطايا ، ثم لقيتني لا تشرك بي شيئا ، لأتيتك بقرابها مغفرة )",
            "رواه الترمذي وقال : حديث حسن صحيح .")
    )

    fun categories(): List<String> = listOf(CAT_JAWAMI, CAT_QURAN, CAT_ANBIYA, CAT_ARBAEEN)

    fun byCategory(category: String): List<DuaItem> = items.filter { it.category == category }

    fun fullText(category: String): String = byCategory(category)
        .joinToString(separator = " ") { "${it.title}. ${it.text}" }
}
